// Cookies do YouTube (vêm da variável privada YOUTUBE_COOKIES do Railway)
const COOKIES_PATH = path.join(os.tmpdir(), 'yt-cookies.txt');
let cookiesOk = false;
function prepararCookies() {
  const raw = process.env.YOUTUBE_COOKIES;
  if (!raw || !raw.trim()) { cookiesOk = false; return; }
  let conteudo = raw.replace(/\r\n/g, '\n').trim();

  // Detecta se veio em base64 (uma linha so, sem tabs) e decodifica
  if (!conteudo.includes('\t') && !conteudo.startsWith('# Netscape') && /^[A-Za-z0-9+/=\s]+$/.test(conteudo)) {
    try {
      const decoded = Buffer.from(conteudo.replace(/\s+/g, ''), 'base64').toString('utf8');
      if (decoded.includes('\t') || decoded.startsWith('# Netscape')) {
        conteudo = decoded;
        console.log('[cortador] cookies vieram em base64, decodificados');
      }
    } catch (e) {}
  }

  if (!conteudo.startsWith('# Netscape')) conteudo = '# Netscape HTTP Cookie File\n' + conteudo;
  try {
    fs.writeFileSync(COOKIES_PATH, conteudo);
    cookiesOk = true;
    const linhas = conteudo.split('\n').filter(l => l && !l.startsWith('#'));
    const comTabs = linhas.filter(l => l.includes('\t')).length;
    console.log(`[cortador] cookies: ${linhas.length} linhas, ${comTabs} com tabs`);
  } catch (e) { cookiesOk = false; }
}
prepararCookies();
console.log('[cortador] cookies:', cookiesOk ? 'carregados' : 'ausentes');

// Proxy (opcional) - 4 variaveis separadas pra evitar dor com URL-encoding
// PROXY_HOST, PROXY_PORT, PROXY_USER, PROXY_PASS
// PROXY_USERS (opcional): lista separada por virgula de usernames, rotaciona aleatoriamente
let PROXY_URL = null;
const PROXY_HOST_RAW = (process.env.PROXY_HOST || '').trim();
const PROXY_PORT_RAW = (process.env.PROXY_PORT || '').trim();
const PROXY_USERS_LIST = (process.env.PROXY_USERS || '').split(',').map(s => s.trim()).filter(s => s);
const PROXY_PASS_RAW = (process.env.PROXY_PASS || '').trim();
const PROXY_USER_RAW = (process.env.PROXY_USER || '').trim();

function getProxyUrl() {
  if (!PROXY_HOST_RAW || !PROXY_PORT_RAW) return '';
  // Se tem lista de usuarios, escolhe aleatoriamente a cada chamada
  let user = PROXY_USER_RAW;
  if (PROXY_USERS_LIST.length > 0) {
    user = PROXY_USERS_LIST[Math.floor(Math.random() * PROXY_USERS_LIST.length)];
  }
  if (user && PROXY_PASS_RAW) {
    return `http://${encodeURIComponent(user)}:${encodeURIComponent(PROXY_PASS_RAW)}@${PROXY_HOST_RAW}:${PROXY_PORT_RAW}`;
  }
  return `http://${PROXY_HOST_RAW}:${PROXY_PORT_RAW}`;
}

// PROXY_URL legado (snapshot inicial pra logs e fallback)
PROXY_URL = getProxyUrl();
if (PROXY_USERS_LIST.length > 0) {
  console.log('[cortador] proxy:', `configurado com ROTACAO de ${PROXY_USERS_LIST.length} usuarios (${PROXY_HOST_RAW}:${PROXY_PORT_RAW})`);
} else if (PROXY_URL) {
  console.log('[cortador] proxy:', `configurado (${PROXY_HOST_RAW}:${PROXY_PORT_RAW})`);
} else {
  console.log('[cortador] proxy:', 'sem proxy');
}

