// Path da Anton (default — mantem retrocompatibilidade)
const FONTE = path.join(os.tmpdir(), FONTES_DISPONIVEIS['anton'].arquivo);
const fontesProntas = {};
function garantirFonte(slug) {
  slug = slug || 'anton';
  const fonteConfig = FONTES_DISPONIVEIS[slug] || FONTES_DISPONIVEIS['anton'];
  const destPath = path.join(os.tmpdir(), fonteConfig.arquivo);
  if (fontesProntas[slug]) return fontesProntas[slug];
  fontesProntas[slug] = new Promise((resolve, reject) => {
    if (fs.existsSync(destPath)) return resolve(destPath);
    const baixar = (url) => {
      https.get(url, (r) => {
        if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) return baixar(r.headers.location);
        if (r.statusCode !== 200) return reject(new Error('Nao consegui baixar a fonte ' + slug + ' (' + r.statusCode + ')'));
        const out = fs.createWriteStream(destPath);
        r.pipe(out);
        out.on('finish', () => out.close(() => { console.log('[cortador] fonte', fonteConfig.nome, 'pronta'); resolve(destPath); }));
        out.on('error', reject);
      }).on('error', reject);
    };
    baixar(fonteConfig.url);
  });
  return fontesProntas[slug];
}

