// ---- Cobalt.tools API (PRIMEIRA TENTATIVA) ----
// URL da instancia propria do Cobalt (hospedada no Railway pela Instructiva)
// Pode ser sobrescrita via env var COBALT_API_URL no Railway
const COBALT_API_URL = (process.env.COBALT_API_URL || 'https://cobalt-production-2fb0.up.railway.app').replace(/\/+$/, '');

function baixarViaCobalt(videoUrl, destPath, modo) {
  // modo: 'video' (default) ou 'audio'
  return new Promise((resolve, reject) => {
    if (!COBALT_API_URL) return reject(new Error('COBALT_API_URL nao configurada'));
    const body = JSON.stringify(modo === 'audio' ? {
      url: videoUrl,
      downloadMode: 'audio',
      audioFormat: 'mp3',
      audioBitrate: '128',
      filenameStyle: 'basic',
      youtubeDubLang: 'pt'
    } : {
      url: videoUrl,
      videoQuality: '1080',
      audioBitrate: '256',
      filenameStyle: 'basic',
      downloadMode: 'auto',
      youtubeVideoCodec: 'h264',
      youtubeHLS: false
    });
    const u = new URL(COBALT_API_URL + '/');
    const req = https.request({
      hostname: u.hostname,
      port: u.port || 443,
      path: '/',
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'User-Agent': 'cortador-instructiva/1.0',
        'Content-Length': Buffer.byteLength(body),
      },
      timeout: 45000,
    }, (r) => {
      let data = '';
      r.on('data', chunk => { data += chunk; });
      r.on('end', () => {
        try {
          const j = JSON.parse(data);
          console.log('[cortador] cobalt status:', j.status, '| http:', r.statusCode);
          if ((j.status === 'tunnel' || j.status === 'redirect' || j.status === 'stream') && j.url) {
            // Cobalt retornou URL de download. Baixa o arquivo.
            const baixarArq = (url, redirs) => {
              if ((redirs || 0) > 5) return reject(new Error('Muitos redirects no download'));
              const downloadUrl = new URL(url);
              const proto = downloadUrl.protocol === 'http:' ? require('http') : https;
              proto.get(url, (resp) => {
                if (resp.statusCode >= 300 && resp.statusCode < 400 && resp.headers.location) {
                  return baixarArq(resp.headers.location, (redirs || 0) + 1);
                }
                if (resp.statusCode !== 200) return reject(new Error('HTTP ' + resp.statusCode + ' baixando do tunnel'));
                const out = fs.createWriteStream(destPath);
                resp.pipe(out);
                out.on('finish', () => out.close(() => {
                  const sz = fs.statSync(destPath).size;
                  console.log('[cortador] cobalt OK:', (sz/1024/1024).toFixed(1), 'MB');
                  resolve();
                }));
                out.on('error', reject);
              }).on('error', reject);
            };
            baixarArq(j.url);
          } else if (j.status === 'picker' && j.picker && j.picker.length > 0) {
            // Cobalt deu varias opcoes - pega primeira
            const primeira = j.picker[0];
            if (primeira.url) {
              const baixarPicker = (url) => {
                https.get(url, (resp) => {
                  if (resp.statusCode >= 300 && resp.statusCode < 400 && resp.headers.location) {
                    return baixarPicker(resp.headers.location);
                  }
                  if (resp.statusCode !== 200) return reject(new Error('HTTP ' + resp.statusCode));
                  const out = fs.createWriteStream(destPath);
                  resp.pipe(out);
                  out.on('finish', () => out.close(() => resolve()));
                  out.on('error', reject);
                }).on('error', reject);
              };
              baixarPicker(primeira.url);
            } else {
              reject(new Error('Picker sem URL valida'));
            }
          } else if (j.status === 'error') {
            const code = (j.error && j.error.code) || 'desconhecido';
            reject(new Error('Cobalt: ' + code));
          } else {
            reject(new Error('Resposta Cobalt inesperada: ' + (j.status || JSON.stringify(j).slice(0, 200))));
          }
        } catch (e) {
          reject(new Error('Resposta Cobalt invalida (' + r.statusCode + '): ' + data.slice(0, 200)));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Cobalt timeout (45s)')); });
    req.write(body);
    req.end();
  });
}


// ---- Gera arquivo ASS estilo Opus Clip (palavras agrupadas, animadas) ----
function gerarLegendaASS(words, inicioCorte, fimCorte, destPath, opcoes) {
  opcoes = opcoes || {};
  const playW = opcoes.playResX || 720;
  const playH = opcoes.playResY || 1280;

  // Tamanho (percentual da largura): S=6.5% M=8.5% L=11%
  const tamMap = { 'S': 0.065, 'M': 0.085, 'L': 0.11 };
  const fatorTam = tamMap[opcoes.tamanho] || tamMap['M'];
  const fontSize = Math.round(playW * fatorTam);

  // Posição vertical
  const posMap = {
    'top': Math.round(playH * 0.18),
    'center': Math.round(playH * 0.50),
    'bottom': Math.round(playH * 0.18)
  };
  const marginV = posMap[opcoes.posicao] || posMap['bottom'];
  // ASS alignment: 8=top, 5=center, 2=bottom
  const alignment = opcoes.posicao === 'top' ? 8 : opcoes.posicao === 'center' ? 5 : 2;

  // Cor (BGR no ASS, opposite of RGB)
  const corMap = {
    'white':  '&H00FFFFFF',
    'yellow': '&H0000F0FF',
    'orange': '&H000C5AEA',  // laranja Instructiva
    'green':  '&H0000F060'
  };
  const corPrincipal = corMap[opcoes.cor] || corMap['white'];
  const corOutline = '&H00000000';

  // Fonte
  const nomeFonteASS = (FONTES_DISPONIVEIS[opcoes.fonte] || FONTES_DISPONIVEIS['anton']).nome;

  const palavrasPorGrupo = opcoes.palavrasPorGrupo || 3;
  const outlineSize = Math.max(3, Math.round(fontSize * 0.07));

  // 1. Pega só palavras dentro do trecho e normaliza tempo
  let palavras = (words || [])
    .filter(w => w.end > inicioCorte && w.start < fimCorte)
    .map(w => ({
      word: String(w.word || '').trim().replace(/[{}\\]/g, ''),
      start: Math.max(0, w.start - inicioCorte),
      end: Math.min(fimCorte - inicioCorte, w.end - inicioCorte)
    }))
    .filter(w => w.word && w.end > w.start);

  // 2. Se texto customizado foi fornecido, sobrescreve as palavras mantendo timing distribuído
  if (opcoes.textoCustom && opcoes.textoCustom.trim()) {
    const palavrasNovas = opcoes.textoCustom.trim().split(/\s+/).filter(p => p);
    if (palavrasNovas.length > 0 && palavras.length > 0) {
      const dur = (fimCorte - inicioCorte);
      const passo = dur / palavrasNovas.length;
      // Mapeia as palavras novas nos tempos: distribui proporcionalmente
      palavras = palavrasNovas.map((w, i) => ({
        word: w.replace(/[{}\\]/g, ''),
        start: i * passo,
        end: (i + 1) * passo
      }));
    }
  }

  if (palavras.length === 0) return false;

  const grupos = [];
  for (let i = 0; i < palavras.length; i += palavrasPorGrupo) {
    grupos.push(palavras.slice(i, i + palavrasPorGrupo));
  }

  const tempoASS = (s) => {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = (s % 60).toFixed(2);
    return `${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(5,'0')}`;
  };

  let conteudo = `[Script Info]
ScriptType: v4.00+
PlayResX: ${playW}
PlayResY: ${playH}
ScaledBorderAndShadow: yes
WrapStyle: 2

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,${nomeFonteASS},${fontSize},${corPrincipal},${corPrincipal},${corOutline},&H80000000,1,0,0,0,100,100,0,0,1,${outlineSize},2,${alignment},30,30,${marginV},1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

  for (const grupo of grupos) {
    const inicio = grupo[0].start;
    const fim = grupo[grupo.length - 1].end;
    let texto = '';
    for (const w of grupo) {
      const duracaoMs = Math.max(1, Math.round((w.end - w.start) * 100));
      texto += `{\\kf${duracaoMs}}${w.word.toUpperCase()} `;
    }
    conteudo += `Dialogue: 0,${tempoASS(inicio)},${tempoASS(fim)},Default,,0,0,0,,${texto.trim()}\n`;
  }

  fs.writeFileSync(destPath, conteudo);
  return true;
}


