const GROQ_API_KEY = (process.env.GROQ_API_KEY || '').trim();
const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || '').trim();

// ---- Extrai audio do video em formato leve pro Groq ----
function extrairAudio(videoPath, audioPath) {
  return new Promise((resolve, reject) => {
    const args = [
      '-y', '-i', videoPath,
      '-vn',                  // sem video
      '-ac', '1',             // mono
      '-ar', '16000',         // 16kHz (Whisper trabalha em 16kHz)
      '-b:a', '32k',          // 32kbps eh suficiente pra fala
      '-f', 'mp3',
      audioPath
    ];
    const p = spawn(FFMPEG, args);
    let stderr = '';
    p.stderr.on('data', d => { stderr += d.toString(); });
    p.on('error', reject);
    p.on('close', code => {
      if (code === 0 && fs.existsSync(audioPath)) resolve();
      else reject(new Error('ffmpeg falhou ao extrair audio: ' + stderr.slice(-300)));
    });
  });
}

// ---- Transcreve audio via Groq (Whisper Large v3 turbo) ----
function transcreverComGroq(audioPath) {
  return new Promise((resolve, reject) => {
    if (!GROQ_API_KEY) return reject(new Error('GROQ_API_KEY nao configurada'));

    const audioBuf = fs.readFileSync(audioPath);
    const filename = path.basename(audioPath);
    const boundary = '----CortadorBoundary' + crypto.randomBytes(8).toString('hex');

    // Monta multipart manualmente (sem dependencia)
    const partes = [];
    const add = (nome, valor) => {
      partes.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="${nome}"\r\n\r\n${valor}\r\n`));
    };

    add('model', 'whisper-large-v3-turbo');
    add('response_format', 'verbose_json');
    add('language', 'pt');
    add('temperature', '0');
    add('timestamp_granularities[]', 'word');
    add('timestamp_granularities[]', 'segment');

    // Arquivo de audio
    partes.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${filename}"\r\nContent-Type: audio/mpeg\r\n\r\n`));
    partes.push(audioBuf);
    partes.push(Buffer.from(`\r\n--${boundary}--\r\n`));

    const body = Buffer.concat(partes);

    const req = https.request({
      hostname: 'api.groq.com',
      path: '/openai/v1/audio/transcriptions',
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + GROQ_API_KEY,
        'Content-Type': 'multipart/form-data; boundary=' + boundary,
        'Content-Length': body.length,
      },
      timeout: 120000,
    }, (r) => {
      let data = '';
      r.on('data', c => { data += c; });
      r.on('end', () => {
        if (r.statusCode !== 200) {
          return reject(new Error('Groq HTTP ' + r.statusCode + ': ' + data.slice(0, 400)));
        }
        try {
          const j = JSON.parse(data);
          // j.text = transcricao completa
          // j.segments = [{ start, end, text }, ...]
          console.log('[cortador] Groq transcreveu', j.segments ? j.segments.length : 0, 'segmentos |', (j.text || '').length, 'chars');
          resolve(j);
        } catch (e) {
          reject(new Error('Resposta Groq invalida: ' + data.slice(0, 200)));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Groq timeout (120s)')); });
    req.write(body);
    req.end();
  });
}

// ---- Analisa transcricao com Gemini e retorna melhores momentos ----
// ---- Transcreve áudio em chunks quando passa do limite do Groq (25MB) ----
async function transcreverComGroqEmChunks(audioPath, duracaoTotalSeg) {
  const tamanho = fs.statSync(audioPath).size;
  const LIMITE_GROQ = 24 * 1024 * 1024; // 24MB pra ter margem do limite de 25MB

  // Se cabe num único request, manda direto
  if (tamanho <= LIMITE_GROQ) {
    return await transcreverComGroq(audioPath);
  }

  // Divide em chunks de ~45 minutos (a 32kbps = ~10.8MB cada)
  const CHUNK_SEG = 45 * 60;
  const numChunks = Math.ceil(duracaoTotalSeg / CHUNK_SEG);
  console.log('[cortador] audio com', (tamanho/1024/1024).toFixed(1), 'MB excede limite. Dividindo em', numChunks, 'chunks de ~45min cada...');

  const todasSegments = [];
  const todasWords = [];
  let textoCompleto = '';

  for (let i = 0; i < numChunks; i++) {
    const offset = i * CHUNK_SEG;
    const duracao = Math.min(CHUNK_SEG, duracaoTotalSeg - offset);
    const chunkPath = audioPath.replace(/\.mp3$/i, '_chunk' + i + '.mp3');

    // Extrai esse chunk (corte rapido com -c copy)
    await new Promise((res, rej) => {
      const args = [
        '-y',
        '-ss', String(offset),
        '-i', audioPath,
        '-t', String(duracao),
        '-c', 'copy',
        chunkPath
      ];
      const p = spawn(FFMPEG, args);
      let stderr = '';
      p.stderr.on('data', d => { stderr += d.toString(); });
      p.on('close', code => code === 0 && fs.existsSync(chunkPath) ? res() : rej(new Error('chunk ' + i + ' falhou: ' + stderr.slice(-200))));
    });

    console.log('[cortador] transcrevendo chunk', (i+1) + '/' + numChunks, '(' + (offset/60).toFixed(0) + 'min →', ((offset+duracao)/60).toFixed(0) + 'min)...');
    const t = await transcreverComGroq(chunkPath);

    // Ajusta timestamps somando o offset do chunk
    (t.segments || []).forEach(s => {
      todasSegments.push({ start: s.start + offset, end: s.end + offset, text: s.text });
    });
    (t.words || []).forEach(w => {
      todasWords.push({ word: w.word, start: w.start + offset, end: w.end + offset });
    });
    textoCompleto += ' ' + (t.text || '');

    try { fs.unlinkSync(chunkPath); } catch (e) {}
  }

  console.log('[cortador] chunks concatenados:', todasSegments.length, 'segmentos |', todasWords.length, 'palavras');
  return {
    text: textoCompleto.trim(),
    segments: todasSegments,
    words: todasWords
  };
}

function analisarComGemini(transcricao, duracaoTotalSeg) {
  return new Promise((resolve, reject) => {
    if (!GEMINI_API_KEY) return reject(new Error('GEMINI_API_KEY nao configurada'));

    // Monta texto com timestamps pra Gemini saber onde corta
    const texto = (transcricao.segments || [])
      .map(s => `[${s.start.toFixed(1)}s] ${s.text.trim()}`)
      .join('\n');

    const prompt = `Voce e um especialista em conteudo viral pra YouTube Shorts, TikTok e Reels.

Analise a transcricao abaixo de uma aula da Escola Instructiva (escola tecnica de eletronica, energia solar, automacao). O publico-alvo sao tecnicos, eletricistas e profissionais da area.

Identifique os ${duracaoTotalSeg > 1800 ? '5-7' : '3-5'} MELHORES momentos pra virar Shorts virais. Criterios:
- Cada Short deve ter entre 20 e 60 segundos
- Momento deve ter um GANCHO claro (informacao surpreendente, dica pratica, erro comum, segredo, comparacao, etc)
- Comeco do trecho deve "fisgar" a atencao na primeira frase
- Conteudo deve ser auto-contido (nao precisar de contexto anterior pra entender)
- Priorize: dicas praticas, erros comuns, comparacoes (X vs Y), reveiacoes (\"poucos sabem que...\")

Retorne APENAS JSON valido (sem markdown, sem explicacao), no formato:
{
  "momentos": [
    {
      "inicio": <numero em segundos>,
      "fim": <numero em segundos>,
      "titulo": "<titulo chamativo, max 60 chars, estilo 'O ERRO que TODO eletricista comete'>",
      "hook": "<frase inicial do Short, primeira coisa que o espectador ve, max 80 chars>",
      "motivo": "<por que esse trecho viraliza, 1 frase>",
      "score": <0-100, sendo 100 = altissima chance viral>,
      "hashtags": ["<5 hashtags relevantes sem o #>"]
    }
  ]
}

Ordena os momentos pelo score (maior primeiro).

TRANSCRICAO:
${texto}`;

    const body = JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.7,
        maxOutputTokens: 16384,
        responseMimeType: 'application/json',
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    const req = https.request({
      hostname: 'generativelanguage.googleapis.com',
      path: '/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_API_KEY,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
      },
      timeout: 90000,
    }, (r) => {
      let data = '';
      r.on('data', c => { data += c; });
      r.on('end', () => {
        if (r.statusCode !== 200) {
          return reject(new Error('Gemini HTTP ' + r.statusCode + ': ' + data.slice(0, 400)));
        }
        try {
          const j = JSON.parse(data);
          const cand = j.candidates && j.candidates[0];
          if (!cand) return reject(new Error('Gemini sem candidates: ' + data.slice(0, 300)));
          const finish = cand.finishReason;
          const conteudo = cand.content && cand.content.parts && cand.content.parts[0] && cand.content.parts[0].text;
          if (!conteudo) {
            return reject(new Error('Gemini sem conteudo (finish: ' + finish + ')'));
          }
          if (finish && finish !== 'STOP') {
            console.log('[cortador] Gemini finishReason:', finish, '| length conteudo:', conteudo.length);
          }
          // Tentar parsear como JSON. Se cortou, tenta consertar fechando arrays/objetos abertos
          let obj;
          try {
            obj = JSON.parse(conteudo);
          } catch (e1) {
            // JSON cortado. Tenta consertar:
            console.log('[cortador] JSON cortado, tentando consertar...');
            let s = conteudo.trim();
            // Remove o ultimo objeto incompleto (depois da ultima virgula)
            const lastCompleteObj = s.lastIndexOf('},');
            if (lastCompleteObj > 0) {
              s = s.slice(0, lastCompleteObj + 1) + ']}';
              try {
                obj = JSON.parse(s);
                console.log('[cortador] JSON consertado com sucesso (descartou ultimo item incompleto)');
              } catch (e2) {
                return reject(new Error('Resposta Gemini truncada e nao consegui consertar (finish: ' + finish + ')'));
              }
            } else {
              return reject(new Error('Resposta Gemini muito curta ou invalida (finish: ' + finish + ')'));
            }
          }
          const momentos = obj.momentos || [];
          console.log('[cortador] Gemini retornou', momentos.length, 'momentos | finish:', finish);
          resolve(momentos);
        } catch (e) {
          reject(new Error('Resposta Gemini invalida: ' + data.slice(0, 300)));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Gemini timeout (60s)')); });
    req.write(body);
    req.end();
  });
}


// ---- Cache de videos baixados (1 hora) ----
const CACHE_DIR = path.join(os.tmpdir(), 'cortador-cache');
const CACHE_TTL_MS = 60 * 60 * 1000;

function cachePathPara(url, ext) {
  const hash = crypto.createHash('md5').update(url).digest('hex');
  return path.join(CACHE_DIR, hash + '.' + (ext || 'mp4'));
}

// Cache de trecho específico (so o pedaço do video, baixado com --download-sections)
function cacheTrechoPath(url, si, sf) {
  const key = url + '|' + Math.floor(si) + '|' + Math.floor(sf);
  const hash = crypto.createHash('md5').update(key).digest('hex');
  return path.join(CACHE_DIR, 'trecho_' + hash + '.mp4');
}

function segParaHMS(s) {
  const h = Math.floor(s/3600);
  const m = Math.floor((s%3600)/60);
  const sec = Math.floor(s%60);
  return String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(sec).padStart(2,'0');
}

// Mapa de downloads em background (url -> Promise) - evita duplicar
const downloadsEmAndamento = new Map();

// Baixa video completo em background depois da analise — assim "Ver trecho" e "Gerar Short" ficam instantaneos
function baixarVideoCompletoBackground(url) {
  if (downloadsEmAndamento.has(url)) {
    console.log('[bg-download] ja em andamento, pulando:', url.slice(0, 60));
    return;
  }
  const cachePath = cachePathPara(url, 'mp4');
  if (fs.existsSync(cachePath) && fs.statSync(cachePath).size > 1024 * 1024) {
    console.log('[bg-download] ja em cache, pulando');
    return;
  }

  const promise = (async () => {
    const t0 = Date.now();
    try {
      console.log('[bg-download] iniciando download em background do video completo...');
      await garantirYtdlp();
      await garantirFfmpeg();
      fs.mkdirSync(CACHE_DIR, { recursive: true });
      const FMT_HQ = 'bv*[height<=1080]+ba/b[height<=1080]/bv*+ba/best';
      const estrategias = [
        'youtube:player_client=tv,web_safari',
        'youtube:player_client=web_safari,default',
        'youtube:player_client=ios',
        'youtube:player_client=tv_embedded,android',
      ];
      for (const ext of estrategias) {
        try { if (fs.existsSync(cachePath)) fs.unlinkSync(cachePath); } catch (e) {}
        const r = await executar(YTDLP, [
          '--no-playlist', '--no-warnings', '--no-progress',
          '--extractor-args', ext,
          ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
          ...(getProxyUrl() ? ['--proxy', getProxyUrl()] : []),
          '--ffmpeg-location', FFMPEG,
          '-N', '4',
          '-f', FMT_HQ,
          '--merge-output-format', 'mp4',
          '-o', cachePath,
          url,
        ], 'yt-dlp-bg');
        if (r.codigo === 0 && fs.existsSync(cachePath) && fs.statSync(cachePath).size > 1024 * 1024) {
          console.log('[bg-download] CONCLUIDO em', ((Date.now()-t0)/1000).toFixed(0), 's |', (fs.statSync(cachePath).size/1024/1024).toFixed(0), 'MB | extractor:', ext);
          return;
        }
      }
      // Tenta Cobalt como ultimo recurso
      if (COBALT_API_URL) {
        try {
          await baixarViaCobalt(url, cachePath);
          if (fs.existsSync(cachePath) && fs.statSync(cachePath).size > 1024 * 1024) {
            console.log('[bg-download] CONCLUIDO via Cobalt em', ((Date.now()-t0)/1000).toFixed(0), 's');
            return;
          }
        } catch (e) {}
      }
      console.log('[bg-download] FALHOU apos', ((Date.now()-t0)/1000).toFixed(0), 's');
    } catch (e) {
      console.log('[bg-download] erro:', e.message);
    } finally {
      downloadsEmAndamento.delete(url);
    }
  })();
  downloadsEmAndamento.set(url, promise);
}


// Mapa de downloads em background — END
async function baixarTrechoYoutube(url, si, sf, destPath) {
  fs.mkdirSync(path.dirname(destPath), { recursive: true });
  const FMT = 'bv*[height<=1080]+ba/b[height<=1080]/bv*+ba/best';
  const estrategias = [
    'youtube:player_client=tv,web_safari',
    'youtube:player_client=web_safari,default',
    'youtube:player_client=ios',
    'youtube:player_client=tv_embedded,android',
  ];
  // Pega ~2s antes e depois pra garantir keyframes
  const siCom = Math.max(0, si - 2);
  const sfCom = sf + 2;
  const secao = '*' + segParaHMS(siCom) + '-' + segParaHMS(sfCom);
  let ultimoErro = '';
  for (const ext of estrategias) {
    console.log('[cortador] baixando trecho', segParaHMS(si), '->', segParaHMS(sf), '| extractor:', ext);
    try { if (fs.existsSync(destPath)) fs.unlinkSync(destPath); } catch (e) {}
    const r = await executar(YTDLP, [
      '--no-playlist', '--no-warnings', '--no-progress',
      '--extractor-args', ext,
      ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
      ...(getProxyUrl() ? ['--proxy', getProxyUrl()] : []),
      '--ffmpeg-location', FFMPEG,
      '-N', '4',
      '--download-sections', secao,
      '-f', FMT,
      '--merge-output-format', 'mp4',
      '-o', destPath,
      url,
    ], 'yt-dlp-trecho');
    if (r.codigo === 0 && fs.existsSync(destPath) && fs.statSync(destPath).size > 100 * 1024) {
      console.log('[cortador] trecho baixado:', (fs.statSync(destPath).size/1024/1024).toFixed(1), 'MB');
      return true;
    }
    ultimoErro = (r.stderr || r.stdout || '').slice(-200);
  }
  console.log('[cortador] falhou baixar trecho:', ultimoErro);
  return false;
}

function limparCacheAntigo() {
  try {
    if (!fs.existsSync(CACHE_DIR)) return;
    const agora = Date.now();
    for (const f of fs.readdirSync(CACHE_DIR)) {
      const fp = path.join(CACHE_DIR, f);
      try {
        const stat = fs.statSync(fp);
        if (agora - stat.mtimeMs > CACHE_TTL_MS) {
          fs.unlinkSync(fp);
          console.log('[cortador] cache: removido', f, '(velho)');
        }
      } catch (e) {}
    }
  } catch (e) {}
}

function linkValido(u) {
  return typeof u === 'string' && /^https:\/\/(www\.|m\.)?(youtube\.com\/|youtu\.be\/)/.test(u.trim());
}
function tempoValido(t) {
  return typeof t === 'string' && /^(\d{1,2}:)?\d{1,2}:\d{2}$|^\d{1,3}(:\d{2}){0,2}$|^\d+$/.test(t.trim());
}
function paraSegundos(t) {
  const p = String(t).trim().split(':').map(Number);
  if (p.some(isNaN)) return NaN;
  return p.reduce((acc, v) => acc * 60 + v, 0);
}

// ============ AUTENTICAÇÃO ============
// Senha do app (env var APP_PASSWORD, default 'instructiva2026')
const APP_PASSWORD = (process.env.APP_PASSWORD || 'instructiva2026').trim();
// Secret pra assinar o cookie de sessão
const AUTH_SECRET = (process.env.AUTH_SECRET || process.env.ADMIN_KEY || 'instructiva-secret-2026').trim();

function gerarToken() {
  return crypto.createHmac('sha256', AUTH_SECRET).update(APP_PASSWORD).digest('hex');
}

function parseCookies(header) {
  const out = {};
  if (!header) return out;
  header.split(';').forEach(c => {
    const idx = c.indexOf('=');
    if (idx < 0) return;
    const k = c.slice(0, idx).trim();
    const v = c.slice(idx + 1).trim();
    if (k) out[k] = decodeURIComponent(v);
  });
  return out;
}

function autenticado(req) {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies['instructiva-auth'];
  return token && token === gerarToken();
}

function requireAuth(req, res, next) {
  if (autenticado(req)) return next();
  // Pra requisições de API (JSON), retorna 401
  const wantsJson = (req.headers.accept || '').includes('application/json') || (req.headers['content-type'] || '').includes('application/json');
  if (wantsJson) return res.status(401).json({ erro: 'Nao autenticado', redirect: '/login' });
  // Senão, redireciona pra /login
  return res.redirect('/login');
}

// Rota GET /login: serve a tela bonita
app.get('/login', (req, res) => {
  // Se já autenticado, manda direto pro app
  if (autenticado(req)) return res.redirect('/');
  res.type('html').send(PAGINA_LOGIN);
});

// Rota POST /login: valida senha e seta cookie
app.post('/login', express.json(), (req, res) => {
  const senha = String(req.body.senha || '').trim();
  if (!senha) return res.status(400).json({ erro: 'Digite a senha.' });
  if (senha !== APP_PASSWORD) {
    // Pequeno delay anti brute force
    setTimeout(() => res.status(401).json({ erro: 'Senha incorreta.' }), 600);
    return;
  }
  const token = gerarToken();
  // Cookie válido por 30 dias
  const maxAge = 60 * 60 * 24 * 30;
  res.setHeader('Set-Cookie', `instructiva-auth=${token}; HttpOnly; Path=/; Max-Age=${maxAge}; SameSite=Lax; Secure`);
  res.json({ ok: true, redirect: '/' });
});

// Rota POST /logout: limpa cookie
