// Retorna texto transcrito de um trecho especifico (pro frontend editar)
app.get('/transcricao-trecho', requireAuth, (req, res) => {
  try {
    const url = String(req.query.url || '').trim();
    const arquivoUploadId = String(req.query.arquivo_upload_id || '').trim();
    const inicio = parseFloat(req.query.inicio);
    const fim = parseFloat(req.query.fim);
    if (isNaN(inicio) || isNaN(fim) || fim <= inicio) {
      return res.status(400).json({ erro: 'parametros inicio/fim invalidos' });
    }
    let cacheKey;
    if (arquivoUploadId && /^[a-zA-Z0-9._-]+$/.test(arquivoUploadId)) {
      cacheKey = 'upload_' + arquivoUploadId;
    } else if (url) {
      cacheKey = crypto.createHash('md5').update(url).digest('hex');
    } else {
      return res.status(400).json({ erro: 'precisa de url ou arquivo_upload_id' });
    }
    const wordsPath = path.join(CACHE_DIR, cacheKey + '.words.json');
    if (!fs.existsSync(wordsPath)) {
      return res.status(404).json({ erro: 'transcricao nao encontrada — analisa com a IA primeiro' });
    }
    const words = JSON.parse(fs.readFileSync(wordsPath, 'utf8'));
    const palavrasDoTrecho = words.filter(w => w.end > inicio && w.start < fim).map(w => w.word);
    const texto = palavrasDoTrecho.join(' ').replace(/\s+/g, ' ').trim();
    res.json({ ok: true, texto, total_palavras: palavrasDoTrecho.length });
  } catch (e) {
    res.status(500).json({ erro: e.message });
  }
});

