app.post('/admin/cookies', express.json({ limit: '2mb' }), (req, res) => {
  const k = (req.query.k || '').trim();
  if (k !== ADMIN_KEY) return res.status(401).json({ erro: 'Chave invalida.' });
  let conteudo = String(req.body.cookies || '').trim();
  if (!conteudo) return res.status(400).json({ erro: 'Cole o conteudo dos cookies.' });
  // Aceita base64 ou texto netscape direto
  if (!conteudo.includes('\t') && !conteudo.startsWith('# Netscape') && /^[A-Za-z0-9+/=\s]+$/.test(conteudo)) {
    try {
      const dec = Buffer.from(conteudo.replace(/\s+/g, ''), 'base64').toString('utf8');
      if (dec.includes('\t') || dec.startsWith('# Netscape')) conteudo = dec;
    } catch (e) {}
  }
  if (!conteudo.startsWith('# Netscape')) conteudo = '# Netscape HTTP Cookie File\n' + conteudo;
  const linhas = conteudo.split('\n').filter(l => l && !l.startsWith('#'));
  const comTabs = linhas.filter(l => l.includes('\t')).length;
  if (comTabs < 3) return res.status(400).json({ erro: 'Formato invalido. Precisa ser cookies.txt do YouTube em formato Netscape.' });
  try {
    fs.writeFileSync(COOKIES_PATH, conteudo);
    cookiesOk = true;
    // Tambem retorna o base64 pro user atualizar a env var do Railway (pra persistir apos deploy)
    const b64 = Buffer.from(conteudo, 'utf8').toString('base64');
    console.log('[cortador] cookies atualizados via admin:', linhas.length, 'linhas');
    res.json({ ok: true, linhas: linhas.length, comTabs, base64: b64 });
  } catch (e) {
    res.status(500).json({ erro: 'Erro salvando cookies: ' + e.message });
  }
});

