app.post('/analisar', requireAuth, upload.single('arquivo'), async (req, res) => {
  const url = String(req.body.url || '').trim();
  const arquivoUpload = req.file;
  if (!url && !arquivoUpload) return res.status(400).json({ erro: 'Cola o link do video ou anexa um arquivo.' });
  if (!GROQ_API_KEY) return res.status(500).json({ erro: 'GROQ_API_KEY nao configurada no servidor.' });
  if (!GEMINI_API_KEY) return res.status(500).json({ erro: 'GEMINI_API_KEY nao configurada no servidor.' });

  let pasta = null;
  const limparUpload = () => { if (arquivoUpload && fs.existsSync(arquivoUpload.path)) { try { fs.unlinkSync(arquivoUpload.path); } catch (e) {} } };
  try {
    // CRITICO: garantir que yt-dlp e ffmpeg estao baixados/disponiveis
    if (!arquivoUpload) await garantirYtdlp();
    await garantirFfmpeg();

    pasta = fs.mkdtempSync(path.join(os.tmpdir(), 'cortador-analise-'));
    const audioPath = path.join(pasta, 'audio.mp3');

    // Decide a fonte do audio:
    // - Se arquivo upload: extrai audio do arquivo
    // - Se YouTube: baixa SO o audio direto (rapido!)
    let fullPath = null; // arquivo de origem (video ou audio bruto)
    let pulaExtracao = false; // se já temos audio mp3 pronto, pula extração
    if (arquivoUpload) {
      // Upload de arquivo: usa direto, vai extrair audio depois
      console.log('[cortador-analisar] usando arquivo enviado:', arquivoUpload.originalname, '|', (arquivoUpload.size/1024/1024).toFixed(1), 'MB');
      fullPath = arquivoUpload.path;
    } else {
      // YouTube: baixar APENAS audio em CASCATA de fallbacks
      console.log('[cortador-analisar] baixando audio (cascata de tentativas)...');
      const tDl0 = Date.now();
      let ok = false;
      let audioOriginal = null;
      let ultimoErro = '';

      // TENTATIVA 1: Cobalt em modo audio (sem cookies necessárias — usa innertube API)
      if (COBALT_API_URL) {
        try {
          const cobaltPath = path.join(pasta, 'audio_cobalt.mp3');
          console.log('[cortador-analisar] tentativa 1: Cobalt audio mode (sem cookies)');
          await baixarViaCobalt(url, cobaltPath, 'audio');
          if (fs.existsSync(cobaltPath) && fs.statSync(cobaltPath).size > 50 * 1024) {
            audioOriginal = cobaltPath;
            ok = true;
            console.log('[cortador-analisar] ✓ Cobalt audio OK em', ((Date.now()-tDl0)/1000).toFixed(1), 's |', (fs.statSync(cobaltPath).size/1024/1024).toFixed(1), 'MB');
          }
        } catch (e) {
          ultimoErro = 'Cobalt: ' + e.message;
          console.log('[cortador-analisar] Cobalt audio falhou:', e.message);
        }
      }

      // TENTATIVA 2: yt-dlp com bestaudio (varias estrategias)
      if (!ok) {
        console.log('[cortador-analisar] tentativa 2: yt-dlp bestaudio');
        const FMT_AUDIO = 'bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio';
        const estrategias = [
          'youtube:player_client=tv,web_safari',
          'youtube:player_client=web_safari,default',
          'youtube:player_client=ios',
          'youtube:player_client=tv_embedded,android',
          'youtube:player_client=mweb',
        ];
        const audioOriginalTpl = path.join(pasta, 'audio_original.%(ext)s');
        for (const ext of estrategias) {
          // Limpa qualquer arquivo anterior
          try {
            for (const f of fs.readdirSync(pasta)) {
              if (f.startsWith('audio_original.')) fs.unlinkSync(path.join(pasta, f));
            }
          } catch (e) {}
          const r = await executar(YTDLP, [
            '--no-playlist', '--no-warnings', '--no-progress',
            '--extractor-args', ext,
            ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
            ...(getProxyUrl() ? ['--proxy', getProxyUrl()] : []),
            '--ffmpeg-location', FFMPEG,
            '-N', '4',
            '-f', FMT_AUDIO,
            '-o', audioOriginalTpl,
            url,
          ], 'yt-dlp-audio');
          try {
            const f = fs.readdirSync(pasta).find(x => x.startsWith('audio_original.'));
            if (r.codigo === 0 && f) {
              const p = path.join(pasta, f);
              if (fs.statSync(p).size > 50 * 1024) {
                audioOriginal = p;
                ok = true;
                console.log('[cortador-analisar] ✓ yt-dlp audio OK em', ((Date.now()-tDl0)/1000).toFixed(1), 's |', (fs.statSync(p).size/1024/1024).toFixed(1), 'MB | extractor:', ext);
                break;
              }
            }
          } catch (e) {}
          ultimoErro = (r.stderr || r.stdout || '').slice(-300);
        }
      }

      // TENTATIVA 3: yt-dlp baixa video COMPLETO (mais lento, último recurso)
      if (!ok) {
        console.log('[cortador-analisar] tentativa 3: yt-dlp video completo (fallback final)');
        const videoFallback = path.join(pasta, 'video_fallback.mp4');
        const FMT_VIDEO = 'b[height<=720]/best';
        const estrategiasVideo = [
          'youtube:player_client=tv,web_safari',
          'youtube:player_client=ios',
          'youtube:player_client=tv_embedded,android',
        ];
        for (const ext of estrategiasVideo) {
          try { if (fs.existsSync(videoFallback)) fs.unlinkSync(videoFallback); } catch (e) {}
          const r = await executar(YTDLP, [
            '--no-playlist', '--no-warnings', '--no-progress',
            '--extractor-args', ext,
            ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
            ...(getProxyUrl() ? ['--proxy', getProxyUrl()] : []),
            '--ffmpeg-location', FFMPEG,
            '-N', '4',
            '-f', FMT_VIDEO,
            '--merge-output-format', 'mp4',
            '-o', videoFallback,
            url,
          ], 'yt-dlp-video-fallback');
          if (r.codigo === 0 && fs.existsSync(videoFallback) && fs.statSync(videoFallback).size > 1024 * 1024) {
            audioOriginal = videoFallback;
            ok = true;
            console.log('[cortador-analisar] ✓ video completo (fallback) OK em', ((Date.now()-tDl0)/1000).toFixed(1), 's | extractor:', ext);
            break;
          }
          ultimoErro = (r.stderr || r.stdout || '').slice(-300);
        }
      }

      if (!ok) {
        limpar(pasta);
        return res.status(500).json({
          erro: 'Não consegui baixar esse vídeo nem por Cobalt nem por yt-dlp. Os cookies podem ter expirado — atualiza no /admin. Ou tenta upload de arquivo.',
          detalhe: ultimoErro
        });
      }
      fullPath = audioOriginal;
    }

    // 2. Extrair audio leve pra mandar pro Groq
    console.log('[cortador-analisar] extraindo audio...');
    const t1 = Date.now();
    await extrairAudio(fullPath, audioPath);
    const tamAudio = fs.statSync(audioPath).size;
    console.log('[cortador-analisar] audio extraido em', ((Date.now()-t1)/1000).toFixed(1), 's |', (tamAudio/1024/1024).toFixed(1), 'MB');

    // Sem limite de tamanho — Groq divide em chunks automaticamente se passar de 24MB

    // 3. Pegar duracao total do video (via ffprobe)
    let duracaoTotal = 0;
    try {
      const probe = await executar(FFMPEG, ['-i', fullPath, '-hide_banner'], 'ffprobe-dur');
      const m = (probe.stderr || '').match(/Duration:\s*(\d+):(\d+):(\d+\.\d+)/);
      if (m) duracaoTotal = parseInt(m[1])*3600 + parseInt(m[2])*60 + parseFloat(m[3]);
    } catch (e) {}
    console.log('[cortador-analisar] duracao total:', duracaoTotal.toFixed(0), 's (' + (duracaoTotal/60).toFixed(1) + ' min)');

    // 4. Transcrever com Groq (divide em chunks de 45min se passar de 24MB)
    console.log('[cortador-analisar] transcrevendo com Groq...');
    const t2 = Date.now();
    const transcricao = await transcreverComGroqEmChunks(audioPath, duracaoTotal);
    console.log('[cortador-analisar] transcricao em', ((Date.now()-t2)/1000).toFixed(1), 's |', (transcricao.words || []).length, 'palavras com timing');

    // Salva transcricao no cache (junto com video) pra /cortar usar nas legendas
    try {
      let cacheKey;
      if (arquivoUpload) {
        cacheKey = 'upload_' + path.basename(arquivoUpload.path);
      } else {
        cacheKey = crypto.createHash('md5').update(url).digest('hex');
      }
      const wordsPath = path.join(CACHE_DIR, cacheKey + '.words.json');
      fs.mkdirSync(CACHE_DIR, { recursive: true });
      fs.writeFileSync(wordsPath, JSON.stringify(transcricao.words || []));
      console.log('[cortador-analisar] transcricao salva pra legendas:', wordsPath);
    } catch (e) { console.log('[cortador-analisar] erro salvando words:', e.message); }

    // 5. Analisar com Gemini
    console.log('[cortador-analisar] analisando com Gemini...');
    const t3 = Date.now();
    const momentos = await analisarComGemini(transcricao, duracaoTotal);
    console.log('[cortador-analisar] analise em', ((Date.now()-t3)/1000).toFixed(1), 's');

    // 6. Limpar e retornar
    limpar(pasta);
    // Mantem arquivo upload pro gerarShortDoMomento usar depois (vai limpar quando expirar)
    res.json({
      ok: true,
      url: url || null,
      arquivo_upload_id: arquivoUpload ? path.basename(arquivoUpload.path) : null,
      duracao_total: duracaoTotal,
      transcricao_chars: (transcricao.text || '').length,
      momentos: momentos
    });

    // 7. Em background, baixa video completo (DESABILITADO - consome muita banda do proxy residencial)
    // Com Webshare residencial + --download-sections, cada trecho é baixado sob demanda em 5-10s,
    // sem precisar do video completo em cache. Isso economiza ~80% do pacote mensal de banda.
    // Se quiser reabilitar: descomenta a linha abaixo
    // if (url && !arquivoUpload) setImmediate(() => baixarVideoCompletoBackground(url));
  } catch (e) {
    console.error('[cortador-analisar] erro:', e.message);
    if (pasta) limpar(pasta);
    limparUpload();
    res.status(500).json({ erro: 'Erro analisando: ' + e.message });
  }
});


// ============================================================
// ============ ROTA /preview — trecho original rapido =========
// ============================================================
app.post('/preview', requireAuth, async (req, res) => {
  const url = String(req.body.url || '').trim();
  const arquivoUploadId = String(req.body.arquivo_upload_id || '').trim();
  const inicio = String(req.body.inicio || '').trim();
  const fim = String(req.body.fim || '').trim();

  if (!tempoValido(inicio) || !tempoValido(fim)) return res.status(400).json({ erro: 'Tempos invalidos.' });
  const si = paraSegundos(inicio);
  const sf = paraSegundos(fim);
  if (isNaN(si) || isNaN(sf) || sf <= si) return res.status(400).json({ erro: 'Fim precisa ser depois do inicio.' });
  if (sf - si > MAX_SEGUNDOS) return res.status(400).json({ erro: 'Trecho muito longo.' });

  // Acha o arquivo de origem
  let fullPath = null;
  let ehTrecho = false; // se já é só o trecho, não precisa cortar de novo
  if (arquivoUploadId && /^[a-zA-Z0-9._-]+$/.test(arquivoUploadId)) {
    const p = path.join(UPLOAD_DIR, arquivoUploadId);
    if (fs.existsSync(p)) fullPath = p;
  } else if (url) {
    // 1) Vídeo completo em cache?
    const cachedFull = cachePathPara(url, 'mp4');
    if (fs.existsSync(cachedFull) && fs.statSync(cachedFull).size > 1024 * 1024) {
      fullPath = cachedFull;
    } else {
      // 2) Trecho específico em cache?
      const cachedTrecho = cacheTrechoPath(url, si, sf);
      if (fs.existsSync(cachedTrecho) && fs.statSync(cachedTrecho).size > 50 * 1024) {
        fullPath = cachedTrecho;
        ehTrecho = true;
        console.log('[cortador-preview] trecho ja em cache:', path.basename(cachedTrecho));
      } else {
        // 3) Baixa APENAS o trecho (rapido!)
        console.log('[cortador-preview] baixando trecho do YouTube...');
        try {
          await garantirYtdlp();
          await garantirFfmpeg();
          fs.mkdirSync(CACHE_DIR, { recursive: true });
          const ok = await baixarTrechoYoutube(url, si, sf, cachedTrecho);
          if (ok) {
            fullPath = cachedTrecho;
            ehTrecho = true;
          }
        } catch (e) { console.log('[cortador-preview] erro:', e.message); }

        // 4) FALLBACK: se trecho falhou, baixa video completo (mais lento mas confiavel)
        if (!fullPath) {
          console.log('[cortador-preview] trecho falhou. Fallback: baixando video COMPLETO...');
          try {
            const FMT_HQ = 'bv*[height<=1080]+ba/b[height<=1080]/bv*+ba/best';
            const estrategias = [
              'youtube:player_client=tv,web_safari',
              'youtube:player_client=web_safari,default',
              'youtube:player_client=ios',
              'youtube:player_client=tv_embedded,android',
            ];
            for (const ext of estrategias) {
              try { if (fs.existsSync(cachedFull)) fs.unlinkSync(cachedFull); } catch (e) {}
              console.log('[cortador-preview] fallback yt-dlp completo, extractor:', ext);
              const r = await executar(YTDLP, [
                '--no-playlist', '--no-warnings', '--no-progress',
                '--extractor-args', ext,
                ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
                ...(getProxyUrl() ? ['--proxy', getProxyUrl()] : []),
                '--ffmpeg-location', FFMPEG,
                '-N', '4',
                '-f', FMT_HQ,
                '--merge-output-format', 'mp4',
                '-o', cachedFull,
                url,
              ], 'yt-dlp-preview-full');
              if (r.codigo === 0 && fs.existsSync(cachedFull) && fs.statSync(cachedFull).size > 1024 * 1024) {
                fullPath = cachedFull;
                ehTrecho = false; // video completo, vai cortar com -ss real
                console.log('[cortador-preview] video completo baixado:', (fs.statSync(cachedFull).size/1024/1024).toFixed(1), 'MB');
                break;
              }
            }
            if (!fullPath && COBALT_API_URL) {
              console.log('[cortador-preview] yt-dlp completo falhou, tentando Cobalt...');
              try {
                await baixarViaCobalt(url, cachedFull);
                if (fs.existsSync(cachedFull) && fs.statSync(cachedFull).size > 1024 * 1024) {
                  fullPath = cachedFull;
                  ehTrecho = false;
                }
              } catch (e) { console.log('[cortador-preview] Cobalt falhou:', e.message); }
            }
          } catch (e) { console.log('[cortador-preview] erro fallback completo:', e.message); }
        }
      }
    }
  }

  if (!fullPath) {
    return res.status(404).json({ erro: 'Nao consegui acessar o video pra fazer preview. Tenta upload do arquivo no botao Arquivo.' });
  }

  let pasta;
  try {
    await garantirFfmpeg();
    pasta = fs.mkdtempSync(path.join(os.tmpdir(), 'preview-'));
    const previewPath = path.join(pasta, 'preview.mp4');

    // Se já é trecho (baixado com --download-sections), o -ss baseline é 0
    // Senão usa o tempo original (si)
    const ssReal = ehTrecho ? Math.max(0, si - (si - 2)) : si; // se ehTrecho, comeca em ~2s (margem de keyframes)
    const ssParam = ehTrecho ? Math.max(0, 2) : si;

    // Tenta corte rapido com -c copy (1-3s, sem reencode)
    const t0 = Date.now();
    const r = await executar(FFMPEG, [
      '-y',
      '-ss', String(ssParam),
      '-i', fullPath,
      '-t', String(sf - si),
      '-c', 'copy',
      '-avoid_negative_ts', 'make_zero',
      '-movflags', '+faststart',
      previewPath,
    ], 'ffmpeg-preview-copy');

    let ok = (r.codigo === 0 && fs.existsSync(previewPath) && fs.statSync(previewPath).size > 50 * 1024);

    // Fallback: reencode ultrafast pra casos onde -c copy falha (keyframe fora do range)
    if (!ok) {
      console.log('[cortador-preview] -c copy falhou, fallback ultrafast');
      try { if (fs.existsSync(previewPath)) fs.unlinkSync(previewPath); } catch (e) {}
      const r2 = await executar(FFMPEG, [
        '-y',
        '-ss', String(ssParam),
        '-i', fullPath,
        '-t', String(sf - si),
        '-c:v', 'libx264',
        '-preset', 'ultrafast',
        '-crf', '28',
        '-c:a', 'aac',
        '-b:a', '128k',
        '-movflags', '+faststart',
        previewPath,
      ], 'ffmpeg-preview-fallback');
      ok = (r2.codigo === 0 && fs.existsSync(previewPath) && fs.statSync(previewPath).size > 50 * 1024);
    }

    if (!ok) {
      limpar(pasta);
      return res.status(500).json({ erro: 'Nao consegui gerar preview.' });
    }

    console.log('[cortador-preview] preview gerado em', ((Date.now()-t0)/1000).toFixed(1), 's |', (fs.statSync(previewPath).size/1024/1024).toFixed(1), 'MB');
    res.download(previewPath, 'preview.mp4', () => limpar(pasta));
  } catch (e) {
    if (pasta) limpar(pasta);
    res.status(500).json({ erro: 'Erro no preview: ' + e.message });
  }
});


